// Reads the Shopify order, skips repeat deliveries and builds the monday.com column values.
// Column IDs come from MONDAY_COLUMNS and MONDAY_SUBITEM_COLUMNS (JSON objects), so any board layout works.
const TOPICS = ['orders/create', 'orders/updated'];
const KEEP_IDS_HOURS = 48; // Shopify retries a failed delivery for up to 4 hours
const COLUMN_KEYS = ['order_number', 'customer', 'email', 'total', 'payment_status', 'fulfillment_status',
  'shipping_method', 'order_date', 'flags', 'shopify_updated_at'];
const SUBITEM_KEYS = ['sku', 'quantity'];
const PAYMENT = { pending: 'Pending', authorized: 'Authorized', partially_paid: 'Partially paid', paid: 'Paid',
  partially_refunded: 'Partially refunded', refunded: 'Refunded', voided: 'Voided', expired: 'Expired' };
const FULFILLMENT = { fulfilled: 'Fulfilled', partial: 'Partially fulfilled', restocked: 'Restocked', not_eligible: 'Not eligible' };

// Config, checked on every run so a typo shows up as a clear error instead of a half written item.
// n8n keeps only the text after the last colon of a Code node error, so messages are made colon free.
const fail = text => { throw new Error(String(text).replace(/\s*:\s*/g, ', ')); };
const readMap = (name, raw, allowed) => {
  let map = {};
  if (raw && String(raw).trim()) {
    try { map = JSON.parse(raw); } catch (e) { map = null; }
    if (!map || typeof map !== 'object' || Array.isArray(map)) fail(`${name} must be a JSON object that maps keys such as ${allowed[0]} to monday column IDs`);
  }
  const unknown = Object.keys(map).filter(k => !allowed.includes(k));
  if (unknown.length) fail(`Unknown key ${unknown.join(', ')} in ${name}. The allowed keys are ${allowed.join(', ')}`);
  return Object.fromEntries(Object.entries(map).map(([k, v]) => [k, String(v || '').trim()]));
};
const columns = readMap('MONDAY_COLUMNS', $env.MONDAY_COLUMNS, COLUMN_KEYS);
const subColumns = readMap('MONDAY_SUBITEM_COLUMNS', $env.MONDAY_SUBITEM_COLUMNS, SUBITEM_KEYS);
const boardId = String($env.MONDAY_BOARD_ID || '').trim();
const groupId = String($env.MONDAY_GROUP_ID || '').trim();
const missing = [];
if (!String($env.MONDAY_API_TOKEN || '').trim()) missing.push('MONDAY_API_TOKEN');
if (!/^\d+$/.test(boardId)) missing.push('MONDAY_BOARD_ID (digits only)');
if (!columns.order_number) missing.push('MONDAY_COLUMNS with an "order_number" column');
if (missing.length) fail(`Missing config. Set ${missing.join(', ')}`);

const vipRaw = String($env.VIP_ORDER_TOTAL ?? '').trim();
const vipTotal = vipRaw === '' ? 500 : Number(vipRaw);
if (!Number.isFinite(vipTotal)) fail(`VIP_ORDER_TOTAL "${vipRaw}" is not a number`);
const rushWords = String($env.RUSH_SHIPPING_KEYWORDS ?? 'express,overnight,next day,priority,rush')
  .split(',').map(w => w.trim().toLowerCase()).filter(Boolean);
const escapeRe = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const rushRes = rushWords.map(w => new RegExp(`(^|[^a-z0-9])${escapeRe(w)}($|[^a-z0-9])`, 'i'));

const titleCase = s => String(s || '').replace(/_/g, ' ').replace(/^./, c => c.toUpperCase());
const isoSeconds = value => { const d = new Date(value); return Number.isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 19) + 'Z'; };
const gidTail = (gid, fallback) => String(gid || '').split('/').pop() || String(fallback ?? '');

// Repeat deliveries: Shopify retries with the same X-Shopify-Webhook-Id. The IDs are kept for 48 hours.
const store = $getWorkflowStaticData('global');
const seen = store.seenWebhookIds || (store.seenWebhookIds = {});
const now = Date.now();
for (const [id, at] of Object.entries(seen)) if (now - at > KEEP_IDS_HOURS * 3600 * 1000) delete seen[id];

const out = [];
$input.all().forEach((item, i) => {
  const h = item.json.headers || {};
  const o = item.json.body || {};
  const topic = String(h['x-shopify-topic'] || '').toLowerCase();
  const webhookId = String(h['x-shopify-webhook-id'] || '');
  const base = { topic, webhookId, shop: String(h['x-shopify-shop-domain'] || '') };
  const skip = reason => out.push({ json: { ...base, skip: true, skipReason: reason }, pairedItem: { item: i } });

  if (!TOPICS.includes(topic)) return skip(`topic "${topic || 'none'}" is not handled`);
  if (webhookId && seen[webhookId]) return skip(`repeat delivery ${webhookId}`);
  if (!o.id || !o.name) fail(`Shopify ${topic} webhook ${webhookId} has no order id or order name`);
  if (webhookId) seen[webhookId] = now;

  const name = [o.customer?.first_name, o.customer?.last_name].filter(Boolean).join(' ').trim()
    || o.billing_address?.name || o.shipping_address?.name || '';
  const email = String(o.email || o.contact_email || o.customer?.email || '').trim();
  const customer = name || email || 'Guest';
  const totalRaw = o.current_total_price ?? o.total_price;
  const total = Number(totalRaw);
  if (totalRaw === null || totalRaw === undefined || totalRaw === '' || !Number.isFinite(total)) fail(`Order ${o.name} has a total of "${totalRaw}", which is not a number`);
  // An order edit that changes the shipping keeps the old line with is_removed: true, so those are left out.
  const shippingLines = (Array.isArray(o.shipping_lines) ? o.shipping_lines : []).filter(s => s && s.is_removed !== true);
  const shipping = shippingLines.map(s => s.title || s.code).filter(Boolean).join(', ') || 'No shipping';
  const payment = PAYMENT[o.financial_status] || titleCase(o.financial_status) || 'Unknown';
  const fulfillment = o.cancelled_at ? 'Cancelled' : (FULFILLMENT[o.fulfillment_status] || (o.fulfillment_status ? titleCase(o.fulfillment_status) : 'Unfulfilled'));
  const createdAt = isoSeconds(o.created_at || o.processed_at);
  const updatedAt = isoSeconds(o.updated_at || o.created_at);
  if (!createdAt) fail(`Order ${o.name} has no valid created_at date (${o.created_at})`);

  // Flags
  const flags = [], reasons = [];
  if (vipTotal > 0 && total >= vipTotal) { flags.push('VIP'); reasons.push(`total ${total.toFixed(2)} is at or above the VIP limit of ${vipTotal}`); }
  const rushLine = shippingLines.find(s => rushRes.some(re => re.test(`${s.title || ''} ${s.code || ''}`)));
  if (rushLine) { flags.push('Rush'); reasons.push(`shipping "${rushLine.title || rushLine.code}" matches a rush keyword`); }

  // Column values in monday's JSON formats. null clears a column on update and is left out on create.
  const values = {};
  const put = (key, value) => { if (columns[key]) values[columns[key]] = value; };
  put('order_number', o.name);
  put('customer', customer);
  put('email', email ? { email, text: email } : null);
  put('total', total.toFixed(2));
  put('payment_status', { label: payment });
  put('fulfillment_status', { label: fulfillment });
  put('shipping_method', shipping);
  put('order_date', { date: createdAt.slice(0, 10), time: createdAt.slice(11, 19) });
  put('flags', flags.length ? { labels: flags } : null);
  put('shopify_updated_at', updatedAt);

  // current_quantity is the quantity after order edits and removals (quantity is the original one).
  // Lines whose current quantity is 0 were removed from the order, so they get no new subitem.
  const lineItems = (Array.isArray(o.line_items) ? o.line_items : []).map((li, n) => ({
    lineItemId: gidTail(li.admin_graphql_api_id, li.id ?? n),
    name: String(li.name || li.title || 'Item').trim().slice(0, 255),
    sku: String(li.sku || '').trim(),
    quantity: Number(li.current_quantity ?? li.quantity) || 0,
  })).filter(li => li.quantity > 0);

  out.push({
    json: {
      ...base, skip: false, boardId, groupId, columns, subColumns,
      order: {
        id: gidTail(o.admin_graphql_api_id, o.id), name: String(o.name), customer, email, total: total.toFixed(2),
        currency: String(o.currency || ''), payment, fulfillment, shipping, createdAt, updatedAt, lineItems,
      },
      itemName: `${o.name} ${customer}`.slice(0, 255),
      flags, flagReasons: reasons,
      createValues: Object.fromEntries(Object.entries(values).filter(([, v]) => v !== null)),
      updateValues: values,
    },
    pairedItem: { item: i },
  });
});
return out;

// monday.com GraphQL client. The same block sits at the top of every "Monday:" node.
// It runs in a Code node, not an HTTP Request node, for two reasons: monday sends most errors back
// with HTTP 200 and an "errors" array, and its rate limit errors say how many seconds to wait
// (retry_in_seconds). Here every GraphQL error fails the step, and rate limits wait as long as monday asks.
