  url: 'https://api.monday.com/v2',
  token: String($env.MONDAY_API_TOKEN || ''),
  version: String($env.MONDAY_API_VERSION || '2026-07'),
  attempts: Math.min(5, Math.max(1, Number($env.MONDAY_MAX_ATTEMPTS) || 4)),
  maxWait: Math.min(60, Math.max(1, Number($env.MONDAY_MAX_WAIT_SECONDS) || 60)),
  budget: 240, // seconds per step (requests and waits), so a step stops itself before n8n's 5 minute Code node limit
  started: Date.now(),
};
const elapsed = () => (Date.now() - MONDAY.started) / 1000;
const WAIT_CODES = ['COMPLEXITY_BUDGET_EXHAUSTED', 'ComplexityException', 'RATE_LIMIT_EXCEEDED', 'Rate Limit Exceeded',
  'FIELD_LIMIT_EXCEEDED', 'maxConcurrencyExceeded', 'IP_RATE_LIMIT_EXCEEDED', 'IDEMPOTENCY_CONFLICT'];
