  for (let attempt = 1; attempt <= MONDAY.attempts; attempt++) {
    let res;
    try {
      res = await this.helpers.httpRequest({ method: 'POST', url: MONDAY.url, headers, body: { query, variables }, json: true,
        returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 30000 });
    } catch (e) {
      res = { statusCode: 0, headers: {}, body: { error_message: String(e.message || e) } };
    }
    let body = res.body;
    if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = { error_message: body.slice(0, 200) }; } }
    body = body || {};
    const errors = Array.isArray(body.errors) ? body.errors : [];
    const status = Number(res.statusCode) || 0;
    if (status === 200 && !errors.length && body.data) {
      const replayed = String((res.headers || {})['idempotency-replayed'] || '').toLowerCase() === 'true';
      return { data: body.data, replayedFromOtherRun: replayed && !mayHaveRun };
