const out = [];
for (const [i, item] of $input.all().entries()) {
  const o = item.json;
  const readIds = [o.columns.order_number, o.columns.flags, o.columns.shopify_updated_at].filter(Boolean);
  const query = `query FindOrder($board: ID!, $column: String!, $value: String!, $columnIds: [String!], $subitemColumnIds: [String!]) {
  items_page_by_column_values(board_id: $board, limit: 10, columns: [{ column_id: $column, column_values: [$value] }]) {
    items { id name url column_values(ids: $columnIds) { id text } subitems { id name column_values(ids: $subitemColumnIds) { id text } } }
  }
}`;
  const { data } = await monday(`Find Order for ${o.order.name}`, query, {
    board: o.boardId, column: o.columns.order_number, value: o.order.name,
    columnIds: readIds, subitemColumnIds: o.subColumns.sku ? [o.subColumns.sku] : ['name'],
  });
  const matches = ((data.items_page_by_column_values || {}).items || [])
    .filter(it => textOf(it, o.columns.order_number).trim().toLowerCase() === o.order.name.toLowerCase())
    .sort((a, b) => Number(a.id) - Number(b.id));
  const match = matches[0];
  let board = null, stale = false;
  if (match) {
    const boardUpdatedAt = o.columns.shopify_updated_at ? textOf(match, o.columns.shopify_updated_at).trim() : '';
    // Shopify does not promise delivery order. An update older than what the board shows is skipped.
    stale = Boolean(boardUpdatedAt) && Date.parse(o.order.updatedAt) < Date.parse(boardUpdatedAt);
    board = {
      itemId: String(match.id), url: match.url, updatedAt: boardUpdatedAt,
      flags: o.columns.flags ? flagsOf(textOf(match, o.columns.flags)) : [],
      subitems: (match.subitems || []).map(s => ({ id: String(s.id), name: s.name || '', sku: o.subColumns.sku ? textOf(s, o.subColumns.sku) : '' })),
    };
  }
  out.push({ json: { ...o, found: Boolean(match), stale, board, duplicateItemIds: matches.slice(1).map(m => String(m.id)) }, pairedItem: { item: i } });
}
return out;

