// and the second run gets the same item back. That run then applies its own values only if they are newer.
const out = [];
for (const [i, item] of $input.all().entries()) {
  const o = item.json;
  const readIds = [o.columns.flags, o.columns.shopify_updated_at].filter(Boolean);
  const query = `mutation CreateOrderItem($board: ID!, ${o.groupId ? '$group: String!, ' : ''}$name: String!, $values: JSON!, $columnIds: [String!]) {
  create_item(board_id: $board, ${o.groupId ? 'group_id: $group, ' : ''}item_name: $name, column_values: $values, create_labels_if_missing: true) {
    id url column_values(ids: $columnIds) { id text }
  }
}`;
  const variables = { board: o.boardId, name: o.itemName, values: JSON.stringify(o.createValues), columnIds: readIds.length ? readIds : ['name'] };
