// monday.com GraphQL client. The same block sits at the top of every "Monday:" node.
// It runs in a Code node, not an HTTP Request node, for two reasons: monday sends most errors back
// with HTTP 200 and an "errors" array, and its rate limit errors say how many seconds to wait
// (retry_in_seconds). Here every GraphQL error fails the step, and rate limits wait as long as monday asks.
const MONDAY = {
  url: 'https://api.monday.com/v2',
  token: String($env.MONDAY_API_TOKEN || ''),
  version: String($env.MONDAY_API_VERSION || '2026-07'),
  attempts: Math.min(5, Math.max(1, Number($env.MONDAY_MAX_ATTEMPTS) || 4)),
  maxWait: Math.min(60, Math.max(1, Number($env.MONDAY_MAX_WAIT_SECONDS) || 60)),
  budget: 240, // seconds per step (requests and waits), so a step stops itself before n8n's 5 minute Code node limit
  started: Date.now(),
};
const elapsed = () => (Date.now() - MONDAY.started) / 1000;
const WAIT_CODES = ['COMPLEXITY_BUDGET_EXHAUSTED', 'ComplexityException', 'RATE_LIMIT_EXCEEDED', 'Rate Limit Exceeded',
  'FIELD_LIMIT_EXCEEDED', 'maxConcurrencyExceeded', 'IP_RATE_LIMIT_EXCEEDED', 'IDEMPOTENCY_CONFLICT'];
const NO_RETRY_CODES = ['DAILY_LIMIT_EXCEEDED', 'API_TEMPORARILY_BLOCKED'];
const sleep = seconds => new Promise(resolve => setTimeout(resolve, seconds * 1000));
// n8n keeps only the text after the last colon of a Code node error, so messages are made colon free.
const plain = text => String(text ?? '').replace(/https?:\/\//g, '').replace(/\s*\n\s*/g, ' ').replace(/\s*:\s*/g, ', ');

// Sends one GraphQL request. Mutations that create something pass an Idempotency-Key, so a retry
// (or a second run doing the same thing at the same moment) gets monday's saved answer instead of a duplicate.
const monday = async (step, query, variables, idempotencyKey) => {
  const headers = { Authorization: MONDAY.token, 'API-Version': MONDAY.version, 'Content-Type': 'application/json' };
  if (idempotencyKey) headers['Idempotency-Key'] = idempotencyKey;
  let problem = '';
  let mayHaveRun = false; // true once an attempt failed in a way where monday may still have done the work
  for (let attempt = 1; attempt <= MONDAY.attempts; attempt++) {
    let res;
    try {
      res = await this.helpers.httpRequest({ method: 'POST', url: MONDAY.url, headers, body: { query, variables }, json: true,
        returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 30000 });
    } catch (e) {
      res = { statusCode: 0, headers: {}, body: { error_message: String(e.message || e) } };
    }
    let body = res.body;
    if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = { error_message: body.slice(0, 200) }; } }
    body = body || {};
    const errors = Array.isArray(body.errors) ? body.errors : [];
    const status = Number(res.statusCode) || 0;
    if (status === 200 && !errors.length && body.data) {
      const replayed = String((res.headers || {})['idempotency-replayed'] || '').toLowerCase() === 'true';
      return { data: body.data, replayedFromOtherRun: replayed && !mayHaveRun };
    }
    const first = errors[0] || {};
    const ext = first.extensions || {};
    const code = String(ext.code || body.error_code || '');
    problem = `with ${code || 'an error'} (HTTP ${status || 'no response'}). ${first.message || body.error_message || 'No error message'}`;
    if (status === 0 || status >= 500) mayHaveRun = true;
    // 423 is monday's "Resource is currently locked, please try again later" (another write to the same board).
    const retry = !NO_RETRY_CODES.includes(code)
      && (status === 0 || status === 423 || status === 429 || status >= 500 || WAIT_CODES.includes(code) || Number(ext.status_code) === 429);
    if (!retry || attempt === MONDAY.attempts) break;
    const asked = Number(ext.retry_in_seconds ?? body.retry_in_seconds ?? (res.headers || {})['retry-after']);
    const wait = Math.min(MONDAY.maxWait, asked > 0 ? asked : 2 * attempt);
    if (elapsed() + wait > MONDAY.budget) { problem += ', still failing after ' + Math.round(elapsed()) + ' seconds'; break; }
    await sleep(wait);
  }
  throw new Error(plain(`monday ${step} failed ${problem}`));
};
const textOf = (item, columnId) => ((item && item.column_values) || []).find(c => c.id === columnId)?.text || '';
const flagsOf = text => String(text || '').split(',').map(s => s.trim()).filter(Boolean);

// One subitem per line item: product name, SKU and quantity. Each one has its own Idempotency-Key,
// so a retry or a second run working on the same order never adds a line twice.
const ADD_LINE = `mutation AddLineItem($parent: ID!, $name: String!, $values: JSON!) {
  create_subitem(parent_item_id: $parent, item_name: $name, column_values: $values) { id name }
}`;
const out = [];
for (const [i, item] of $input.all().entries()) {
  const o = item.json;
  const lines = o.subitemsToCreate || [];
  let added = 0;
  for (const [n, li] of lines.entries()) {
    // Very large orders: stop before n8n ends the step at 5 minutes, so the alert says how far it got.
    if (elapsed() > MONDAY.budget) throw new Error(plain(`monday Add Line Items for ${o.order.name} stopped after ${added} of ${lines.length} lines to stay inside the n8n Code node time limit. The next update of this order adds the missing lines.`));
    const values = {};
    if (o.subColumns.sku && li.sku) values[o.subColumns.sku] = li.sku;
    if (o.subColumns.quantity) values[o.subColumns.quantity] = String(li.quantity);
    try {
      await monday(`Add Line Item for ${o.order.name}`, ADD_LINE, { parent: o.itemId, name: li.name, values: JSON.stringify(values) },
        `shopify-line:${o.boardId}:${o.order.id}:${li.lineItemId}`);
    } catch (e) {
      throw new Error(plain(`${e.message}. Line ${n + 1} of ${lines.length} (${li.name}) and any after it were not added, ${added} added before it. The next update of this order adds the missing lines.`));
    }
    added += 1;
  }
  out.push({ json: { ...o, subitemsAdded: added }, pairedItem: { item: i } });
}
return out;

// Writes the Slack alert for VIP and rush orders. Each flag is announced once: on a new order,
// or when an update adds a flag the board did not show yet.
// Names, emails and shipping titles come from the order, so a shopper could type Slack markup such as
// <!channel> or <https://...|text> into them. Slack's rule is to escape &, < and > in such text.
const safe = text => String(text ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const out = [];
$input.all().forEach((item, i) => {
  const o = item.json;
  let newFlags = o.createdHere ? o.flags : o.flags.filter(f => !(o.boardFlags || []).includes(f));
  if (!o.createdHere && !o.columns.flags) newFlags = []; // without a flags column there is no record of earlier alerts
  const lines = [];
  const name = safe(o.order.name);
  if (newFlags.length) {
    const label = newFlags.join(' + ');
    const reasons = o.flagReasons.filter((r, n) => newFlags.includes(o.flags[n]));
    const units = o.order.lineItems.reduce((sum, li) => sum + li.quantity, 0);
    lines.push(o.createdHere ? `*${label} order ${name}*` : `*Order ${name} is now ${label}*`, '',
      `Customer: ${safe(o.order.customer)}${o.order.email ? ` (${safe(o.order.email)})` : ''}`,
      `Total: ${o.order.total}${o.order.currency ? ' ' + safe(o.order.currency) : ''}`,
      `Shipping: ${safe(o.order.shipping)}`,
      `Payment: ${safe(o.order.payment)}`,
      `Line items: ${o.order.lineItems.length} (${units} ${units === 1 ? 'unit' : 'units'})`,
      `Why: ${safe(reasons.join('; '))}`,
      `Open in monday.com: ${o.itemUrl}`);
  }
  if ((o.duplicateItemIds || []).length) {
    if (!lines.length) lines.push(`*Order ${name} has duplicate items on the board*`);
    lines.push(`Note: ${o.duplicateItemIds.length + 1} items have order number ${name}. Item ${o.itemId} was updated. Please merge or delete item ${o.duplicateItemIds.join(', ')}.`);
  }
  out.push({ json: { ...o, alertText: lines.join('\n') }, pairedItem: { item: i } });
});
return out;
